package com.quicknotes.app;
import android.app.*;import android.appwidget.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
public class WidgetConfigActivity extends Activity {
 Spinner list,theme;Switch complete;ChoiceAdapter choices;int widgetId;boolean dark;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle b){dark=ReminderWidget.appDark(this);setTheme(dark?android.R.style.Theme_Material:android.R.style.Theme_Material_Light);super.onCreate(b);getWindow().setStatusBarColor(dark?0xff202124:0xfff2f2f7);getWindow().setNavigationBarColor(dark?0xff202124:0xfff2f2f7);setResult(RESULT_CANCELED);widgetId=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);if(widgetId<0){finish();return;}ScrollView scroll=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(20),dp(24),dp(20),dp(24));box.setBackgroundColor(dark?0xff202124:0xfff2f2f7);scroll.addView(box);setContentView(scroll);label(box,"Customize QuickNotes widget",24);label(box,"List · earliest due reminders first",14);
  choices=new ChoiceAdapter(this,WidgetChoices.all(this),dark);list=new Spinner(this);list.setContentDescription("Widget list");list.setAdapter(choices);list.setPopupBackgroundDrawable(new ColorDrawable(dark?0xff202124:0xfff2f2f7));list.setSelection(choices.position(ReminderWidget.prefs(this).getString(widgetId+"list","all")));box.addView(list,new LinearLayout.LayoutParams(-1,-2));
  label(box,"Appearance",16);theme=new Spinner(this);List<String> themes=Arrays.asList("app","system","light","dark");theme.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,Arrays.asList("App theme","System theme","Light","Dark")));theme.setSelection(Math.max(0,themes.indexOf(ReminderWidget.prefs(this).getString(widgetId+"theme","app"))));box.addView(theme);complete=new Switch(this);complete.setText("Complete reminders in this widget");complete.setTextColor(dark?0xffeeeeee:0xff222222);complete.setChecked(ReminderWidget.canComplete(this,widgetId));complete.setPadding(0,dp(20),0,dp(20));box.addView(complete);label(box,"Resize on your home screen. Tap + to add, a check circle to complete, a row to edit, or ⚙ to change widget settings.",14);Button save=new Button(this);save.setText("Save widget");box.addView(save);save.setOnClickListener(v->{WidgetChoices.Choice choice=(WidgetChoices.Choice)list.getSelectedItem();if(choice==null||choice.header)return;ReminderWidget.prefs(this).edit().putString(widgetId+"list",choice.id).putString(widgetId+"theme",themes.get(theme.getSelectedItemPosition())).putBoolean(widgetId+"complete",complete.isChecked()).commit();ReminderWidget.update(this,widgetId);setResult(RESULT_OK,new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,widgetId));finish();});
 }
 void label(LinearLayout box,String text,int size){TextView v=new TextView(this);v.setText(text);v.setTextSize(size);v.setTextColor(dark?0xffeeeeee:0xff222222);v.setPadding(0,dp(8),0,dp(12));box.addView(v);}
 static class ChoiceAdapter extends BaseAdapter {
  final Context c;final List<WidgetChoices.Choice> items;final boolean dark;
  ChoiceAdapter(Context c,List<WidgetChoices.Choice> items,boolean dark){this.c=c;this.items=items;this.dark=dark;}
  int dp(int n){return (int)(n*c.getResources().getDisplayMetrics().density+.5f);}
  int position(String id){for(int n=0;n<items.size();n++)if(!items.get(n).header&&items.get(n).id.equals(id))return n;return 1;}
  public int getCount(){return items.size();}public Object getItem(int p){return items.get(p);}public long getItemId(int p){return p;}public boolean areAllItemsEnabled(){return false;}public boolean isEnabled(int p){return !items.get(p).header;}
  public View getView(int p,View convert,ViewGroup parent){return row(p);}public View getDropDownView(int p,View convert,ViewGroup parent){return row(p);}
  View row(int p){WidgetChoices.Choice choice=items.get(p);LinearLayout root=new LinearLayout(c);root.setPadding(dp(12),dp(12),dp(12),dp(12));if(choice.header){root.setOrientation(1);View line=new View(c);line.setBackgroundColor(dark?0xff666666:0xffbbbbbb);root.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));TextView title=new TextView(c);title.setText(choice.title);title.setTextSize(13);title.setTextColor(dark?0xffcccccc:0xff555555);title.setPadding(0,dp(10),0,0);root.addView(title);return root;}root.setGravity(Gravity.CENTER_VERTICAL);int base=dark?0xff202124:0xfff2f2f7,color=choice.color;GradientDrawable bg=new GradientDrawable();bg.setColor(Color.rgb((Color.red(base)*88+Color.red(color)*12)/100,(Color.green(base)*88+Color.green(color)*12)/100,(Color.blue(base)*88+Color.blue(color)*12)/100));bg.setCornerRadius(dp(12));bg.setStroke(dp(1),color);root.setBackground(bg);TextView icon=new TextView(c);icon.setText(WidgetChoices.symbol(choice.icon));icon.setTextSize(20);icon.setGravity(Gravity.CENTER);icon.setTextColor(Color.WHITE);GradientDrawable circle=new GradientDrawable();circle.setColor(color);circle.setShape(GradientDrawable.OVAL);icon.setBackground(circle);root.addView(icon,new LinearLayout.LayoutParams(dp(36),dp(36)));TextView title=new TextView(c);title.setText(choice.title);title.setTextColor(dark?0xffeeeeee:0xff222222);title.setTextSize(17);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,-2,1);params.setMargins(dp(12),0,0,0);root.addView(title,params);return root;}
 }
}
